sys_script_include.script:
var ArtmCatalogUtilsAjax = Class.create();
ArtmCatalogUtilsAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    checkGroupMember: function() {
        var propName = this.getParameter('sysparm_grpprop').toString();
        // gs.addErrorMessage("propName groupe = " + propName);

        var groupSysId = gs.getProperty(propName);
        var isMember = gs.getUser().isMemberOf(groupSysId) || gs.hasRole("admin");
        //  gs.addErrorMessage("ismember = " + isMember);
        return isMember;
    },

    checkmanager: function() {
        var userid = this.getParameter('sysparm_user_id');
        var user = new GlideRecord('sys_user');
        if (user.get(userid)) { 
                return user.manager;

        }
        return '';
    },


    type: 'ArtmCatalogUtilsAjax'
});
